const categories=['Tất cả công cụ','Lập trình','Văn bản','Bảo mật','Thiết kế'];
const tools=[
{id:'json',name:'JSON Formatter',desc:'Định dạng, thu gọn và kiểm tra dữ liệu JSON.',cat:'Lập trình',icon:'{ }',tone:'#547a59',tint:'#edf4e9'},
{id:'base64',name:'Base64 Encode / Decode',desc:'Mã hóa và giải mã Base64, hỗ trợ tiếng Việt.',cat:'Lập trình',icon:'B₆₄',tone:'#6b72a0',tint:'#eeedf7'},
{id:'url',name:'URL Encode / Decode',desc:'Chuyển đổi ký tự đặc biệt trong đường dẫn URL.',cat:'Lập trình',icon:'↗',tone:'#56878e',tint:'#e8f2f3'},
{id:'uuid',name:'UUID Generator',desc:'Tạo UUID v4 ngẫu nhiên cho ứng dụng của bạn.',cat:'Lập trình',icon:'#',tone:'#a68b56',tint:'#f7f0e1'},
{id:'password',name:'Tạo mật khẩu',desc:'Tạo mật khẩu ngẫu nhiên với độ dài tùy chọn.',cat:'Bảo mật',icon:'✳',tone:'#92759c',tint:'#f2ecf5'},
{id:'words',name:'Đếm từ & ký tự',desc:'Thống kê từ, ký tự và thời gian đọc văn bản.',cat:'Văn bản',icon:'Aa',tone:'#b17e67',tint:'#f8eee8'},
{id:'case',name:'Chuyển đổi kiểu chữ',desc:'Đổi chữ hoa, chữ thường và viết hoa đầu từ.',cat:'Văn bản',icon:'Tt',tone:'#7f8e54',tint:'#f0f3e5'},
{id:'slug',name:'Tạo slug tiếng Việt',desc:'Biến tiêu đề thành đường dẫn gọn gàng, dễ đọc.',cat:'Văn bản',icon:'a-b',tone:'#567f94',tint:'#eaf1f6'},
{id:'color',name:'Chuyển đổi màu sắc',desc:'Chuyển mã màu HEX sang RGB và HSL.',cat:'Thiết kế',icon:'◉',tone:'#b07e8a',tint:'#f8ecf0'},
{id:'timestamp',name:'Unix Timestamp',desc:'Chuyển đổi thời gian Unix và ngày giờ địa phương.',cat:'Lập trình',icon:'◷',tone:'#698d88',tint:'#eaf4ef'},
{id:'lines',name:'Xử lý dòng văn bản',desc:'Xóa dòng trùng lặp, sắp xếp và bỏ dòng trống.',cat:'Văn bản',icon:'≡',tone:'#8a7b60',tint:'#f3f0e9'},
{id:'percent',name:'Tính phần trăm',desc:'Tính tỷ lệ phần trăm nhanh cho công việc hàng ngày.',cat:'Văn bản',icon:'%',tone:'#6d7da9',tint:'#eef1fa'}];
const $=s=>document.querySelector(s);let category=categories[0],view='all',current;let favorites=[],recent=[];try{favorites=JSON.parse(localStorage.getItem('toolhub-favorites')||'[]');recent=JSON.parse(localStorage.getItem('toolhub-recent')||'[]')}catch{}const save=()=>{try{localStorage.setItem('toolhub-favorites',JSON.stringify(favorites));localStorage.setItem('toolhub-recent',JSON.stringify(recent))}catch{}};
function renderNav(){ $('#nav').innerHTML=categories.map((c,i)=>`<button data-cat="${c}" class="${category===c&&view==='all'?'active':''}"><i>${['▦','⌘','Tt','♧','◈'][i]}</i>${c}${!i?'<span class="num">12</span>':''}</button>`).join('')+`<div class="nav-divider"></div><button data-view="favorites" class="${view==='favorites'?'active':''}"><i>☆</i>Yêu thích<span class="num">${favorites.length}</span></button><button data-view="recent" class="${view==='recent'?'active':''}"><i>◷</i>Đã dùng gần đây</button>`;$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{view=b.dataset.view||'all';category=b.dataset.cat||categories[0];render()})}
function render(){renderNav();$('#filters').innerHTML=categories.map(c=>`<button class="${category===c?'active':''}" data-filter="${c}">${c}</button>`).join('');$('#filters').querySelectorAll('button').forEach(b=>b.onclick=()=>{category=b.dataset.filter;view='all';render()});let query=$('#search').value.toLocaleLowerCase('vi');let list=tools.filter(t=>(category===categories[0]||t.cat===category)&&(view==='all'||(view==='favorites'?favorites:recent).includes(t.id))&&(t.name+' '+t.desc+' '+t.cat).toLocaleLowerCase('vi').includes(query));if(view==='recent')list.sort((a,b)=>recent.indexOf(a.id)-recent.indexOf(b.id));let title=view==='favorites'?'Công cụ yêu thích':view==='recent'?'Đã dùng gần đây':category;$('#crumb').textContent=title;$('#sectionTitle').textContent=title+' ';let count=document.createElement('span');count.textContent=list.length;$('#sectionTitle').append(count);$('#grid').innerHTML=list.map(t=>`<article class="card" style="--tone:${t.tone};--tint:${t.tint}"><button class="favorite ${favorites.includes(t.id)?'selected':''}" aria-label="${favorites.includes(t.id)?'Bỏ':'Thêm'} yêu thích ${t.name}" data-fav="${t.id}">${favorites.includes(t.id)?'★':'☆'}</button><button class="card-main" data-open="${t.id}"><span class="icon">${t.icon}</span><h3>${t.name}</h3><p>${t.desc}</p><div class="card-bottom"><span>${t.cat.toLocaleUpperCase('vi')}</span><span>Mở công cụ →</span></div></button></article>`).join('');$('#empty').hidden=!!list.length;$('#emptyMessage').textContent=view==='favorites'&&!query?'Chưa có công cụ yêu thích. Nhấn ngôi sao trên công cụ bạn thường dùng.':view==='recent'&&!query?'Các công cụ bạn mở sẽ xuất hiện tại đây.':'Không tìm thấy công cụ. Hãy thử từ khóa khác.';$('#grid').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openTool(b.dataset.open));$('#grid').querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{let id=b.dataset.fav;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];save();render()})}
const textInput='<label for="input">Nội dung đầu vào</label><textarea id="input" placeholder="Dán hoặc nhập nội dung tại đây…"></textarea>';const field=(id,label,value,type='text')=>`<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${value}">`;
function prepareTool(id){current=tools.find(t=>t.id===id);recent=[id,...recent.filter(x=>x!==id)].slice(0,12);save();$('#toolTitle').textContent=current.name;$('#toolCategory').textContent=current.cat;$('#toolDesc').textContent=current.desc;$('#output').value='';$('#status').textContent='';let actions=[];$('#fields').innerHTML=['uuid','password'].includes(id)?field('amount',id==='uuid'?'Số lượng UUID (1–100)':'Độ dài mật khẩu (8–128)',id==='uuid'?5:20,'number'):id==='color'?field('input','Mã màu HEX','#236b52'):id==='timestamp'?field('input','Unix timestamp (giây) hoặc ngày giờ ISO',Math.floor(Date.now()/1000)):id==='percent'?field('part','Giá trị phần',25,'number')+field('total','Giá trị tổng',200,'number'):textInput;
if(id==='json')actions=[['Định dạng',()=>JSON.stringify(JSON.parse(val()),null,2)],['Thu gọn',()=>JSON.stringify(JSON.parse(val()))]];
if(id==='base64')actions=[['Mã hóa',()=>btoa(Array.from(new TextEncoder().encode(val()),x=>String.fromCharCode(x)).join(''))],['Giải mã',()=>new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(atob(val().trim()),c=>c.charCodeAt(0)))]];
if(id==='url')actions=[['Mã hóa',()=>encodeURIComponent(val())],['Giải mã',()=>decodeURIComponent(val())]];
if(id==='uuid')actions=[['Tạo UUID',()=>Array.from({length:bounded('amount',1,100)},()=>crypto.randomUUID()).join('\n')]];
if(id==='password')actions=[['Tạo mật khẩu',()=>{let n=bounded('amount',8,128),chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*+-=?';let s='';while(s.length<n){let a=crypto.getRandomValues(new Uint8Array(n*2));for(let x of a)if(x<256-256%chars.length&&s.length<n)s+=chars[x%chars.length]}return s}]];
if(id==='words')actions=[['Đếm văn bản',()=>{let s=val(),n=s.trim()?s.trim().split(/\s+/u).length:0;return `${n} từ\n${Array.from(s).length} ký tự (có khoảng trắng)\n${Array.from(s.replace(/\s/gu,'')).length} ký tự (không có khoảng trắng)\n${s?s.split(/\n/).length:0} dòng\nThời gian đọc: ${n?Math.ceil(n/200):0} phút (ước tính)`}]];
if(id==='case')actions=[['CHỮ HOA',()=>val().toLocaleUpperCase('vi')],['chữ thường',()=>val().toLocaleLowerCase('vi')],['Viết Hoa Đầu Từ',()=>val().toLocaleLowerCase('vi').replace(/(^|\s)(\p{L})/gu,(_,s,c)=>s+c.toLocaleUpperCase('vi'))]];
if(id==='slug')actions=[['Tạo slug',()=>val().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')]];
if(id==='lines')actions=[['Xóa dòng trùng',()=>[...new Set(val().split('\n'))].join('\n')],['Sắp xếp A–Z',()=>val().split('\n').sort((a,b)=>a.localeCompare(b,'vi')).join('\n')],['Bỏ dòng trống',()=>val().split('\n').filter(s=>s.trim()).join('\n')]];
if(id==='percent')actions=[['Tính phần trăm',()=>{let a=Number($('#part').value),b=Number($('#total').value);if(!$('#part').value||!$('#total').value||!Number.isFinite(a)||!Number.isFinite(b)||b===0)throw Error('Nhập hai số hợp lệ; giá trị tổng phải khác 0.');return `${a} / ${b} × 100 = ${Number((a/b*100).toFixed(6))}%`}]];
if(id==='timestamp')actions=[['Chuyển đổi',()=>{let v=val().trim(),d=/^-?\d+$/.test(v)?new Date(Number(v)*1000):new Date(v);if(isNaN(d.getTime()))throw Error('Nhập timestamp theo giây hoặc ngày ISO, ví dụ 2026-10-19T09:00:00+07:00.');return `Unix (giây): ${Math.floor(d.getTime()/1000)}\nISO: ${d.toISOString()}\nĐịa phương: ${d.toLocaleString('vi-VN')}\nMúi giờ: ${Intl.DateTimeFormat().resolvedOptions().timeZone}`}]];
if(id==='color')actions=[['Chuyển đổi màu',()=>{let hex=val().trim().replace(/^#/,'');if(!/^(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(hex))throw Error('Nhập mã HEX gồm 3 hoặc 6 ký tự, ví dụ #236b52.');if(hex.length===3)hex=[...hex].map(c=>c+c).join('');let rgb=[0,2,4].map(i=>parseInt(hex.slice(i,i+2),16)),[r,g,b]=rgb.map(v=>v/255),max=Math.max(r,g,b),min=Math.min(r,g,b),l=(max+min)/2,d=max-min,h=0,s=0;if(d){s=d/(1-Math.abs(2*l-1));h=(max===r?(g-b)/d+(g<b?6:0):max===g?(b-r)/d+2:(r-g)/d+4)*60}return `HEX: #${hex.toUpperCase()}\nRGB: rgb(${rgb.join(', ')})\nHSL: hsl(${Math.round(h)}, ${Math.round(s*100)}%, ${Math.round(l*100)}%)`}]];
$('#actions').innerHTML='';actions.forEach(([label,fn])=>{let b=document.createElement('button');b.textContent=label;b.onclick=()=>{try{$('#output').value=fn();$('#status').textContent='Đã xử lý trên trình duyệt.';$('#status').style.color='';$('#status').dataset.error='false'}catch(e){$('#output').value='';$('#status').textContent=id==='json'?'JSON chưa hợp lệ. Kiểm tra dấu ngoặc, dấu phẩy và dấu nháy kép.':id==='base64'?'Nội dung Base64 hoặc UTF-8 chưa hợp lệ.':id==='url'?'Chuỗi URL chưa hợp lệ. Kiểm tra các ký tự mã hóa %.':e.message;$('#status').style.color='#b14e3e';$('#status').dataset.error='true'}syncResult();rememberDraft();};$('#actions').append(b)});if(!$('#dialog').open)$('#dialog').showModal();render();}
function val(){return $('#input').value}function bounded(id,min,max){let n=Number($('#'+id).value);if(!Number.isInteger(n)||n<min||n>max)throw Error(`Nhập số nguyên từ ${min} đến ${max}.`);return n}
$('#close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){let r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close()}});$('#copy').onclick=async()=>{if(!$('#output').value)return;try{await navigator.clipboard.writeText($('#output').value);$('#status').textContent='Đã sao chép kết quả.'}catch{$('#output').select();$('#status').textContent='Nhấn Ctrl+C hoặc ⌘C để sao chép.'}};$('#search').oninput=render;document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{$('#search').value=b.dataset.query;render()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#dialog').open){e.preventDefault();$('#search').focus()}});$('#share').href='mailto:?subject=ToolHub&body='+encodeURIComponent('Bộ công cụ cho công việc mỗi ngày: '+location.href);render();

// The native dialog provides focus containment and Escape behavior for the workspace.
const drafts=new Map();let activeAction=0,autoTimer;
const examples={json:'{"project":"ToolHub","language":"Tiếng Việt","tools":["JSON","Base64"],"ready":true}',base64:'Xin chào Việt Nam!',url:'https://example.com/tìm kiếm?q=công cụ',words:'ToolHub giúp bạn xử lý những công việc nhỏ mỗi ngày.\nDán nội dung và xem thống kê tại đây.',case:'xin chào, đây là ToolHub',slug:'10 công cụ hữu ích dành cho lập trình viên',color:'#236b52',timestamp:'2026-10-19T09:00:00+07:00',lines:'Thiết kế\nLập trình\nThiết kế\n\nViết nội dung'};
function rememberDraft(){if(!current)return;drafts.set(current.id,{fields:[...$('#fields').querySelectorAll('input,textarea')].map(el=>[el.id,el.value]),output:$('#output').value,status:$('#status').textContent,error:$('#status').dataset.error==='true',action:activeAction,auto:$('#autoRun').checked});}
function syncResult(){const value=$('#output').value;['copy','download','showResult'].forEach(id=>$('#'+id).disabled=!value);$('#reuse').disabled=!value||!$('#fields textarea');$('#reuse').hidden=!$('#fields textarea');$('#resultMeta').textContent=value?`${Array.from(value).length.toLocaleString('vi-VN')} ký tự · ${value.split('\n').length} dòng`:'Chưa có kết quả';$('#fields').querySelectorAll('input,textarea').forEach(el=>el.setAttribute('aria-invalid',$('#status').dataset.error==='true'?'true':'false'));}
function chooseAction(index){activeAction=index;$('#actions').querySelectorAll('button').forEach((b,i)=>{b.classList.toggle('chosen',i===index);b.setAttribute('aria-pressed',String(i===index))});}
function runAction(){const button=$('#actions').children[activeAction];if(button)button.click();}
function openTool(id){clearTimeout(autoTimer);rememberDraft();const draft=drafts.get(id);prepareTool(id);$('#toolSelect').value=id;$('#status').dataset.error='false';$('#status').style.color='';activeAction=draft?.action||0;const random=['uuid','password'].includes(id);$('#autoRun').closest('label').hidden=random;$('#autoRun').checked=draft?.auto??['words','slug','color','percent'].includes(id);$('#example').hidden=random;$('#clear').hidden=random;
const numeric=$('#amount');if(numeric){numeric.min=id==='uuid'?1:8;numeric.max=id==='uuid'?100:128;numeric.step=1;}
$('#fields').querySelectorAll('input,textarea').forEach(el=>{el.setAttribute('aria-describedby','status');el.spellcheck=false;el.addEventListener('input',()=>{clearTimeout(autoTimer);$('#output').value='';$('#status').textContent='';$('#status').dataset.error='false';syncResult();rememberDraft();if($('#autoRun').checked)autoTimer=setTimeout(()=>{if(el.value.trim())runAction()},300)});el.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();clearTimeout(autoTimer);runAction()}})});
$('#actions').querySelectorAll('button').forEach((button,i)=>{const handler=button.onclick;button.onclick=()=>{clearTimeout(autoTimer);chooseAction(i);handler()}});chooseAction(activeAction);
if(draft){draft.fields.forEach(([key,value])=>{const el=$('#'+key);if(el)el.value=value});$('#output').value=draft.output;$('#status').textContent=draft.status;$('#status').dataset.error=String(draft.error);$('#status').style.color=draft.error?'#b14e3e':'';}syncResult();
if(!draft&&(random||['percent','color','timestamp'].includes(id)))runAction();$('#dialog').scrollTop=0;$('#fields').querySelector('textarea,input')?.focus({preventScroll:true});}
$('#toolSelect').innerHTML=categories.slice(1).map(category=>`<optgroup label="${category}">${tools.filter(t=>t.cat===category).map(t=>`<option value="${t.id}">${t.name}</option>`).join('')}</optgroup>`).join('');$('#toolSelect').onchange=e=>openTool(e.target.value);
$('#example').onclick=()=>{clearTimeout(autoTimer);if(current.id==='percent'){$('#part').value=25;$('#total').value=200}else $('#input').value=examples[current.id]||'';chooseAction(0);runAction();$('#fields').querySelector('textarea,input')?.focus({preventScroll:true})};
$('#clear').onclick=()=>{clearTimeout(autoTimer);$('#fields').querySelectorAll('input,textarea').forEach(el=>el.value='');$('#output').value='';$('#status').textContent='';$('#status').dataset.error='false';syncResult();rememberDraft();$('#fields').querySelector('textarea,input')?.focus({preventScroll:true})};
$('#autoRun').onchange=()=>{rememberDraft();clearTimeout(autoTimer);if($('#autoRun').checked&&$('#fields').querySelector('input,textarea')?.value.trim())runAction()};
$('#reuse').onclick=()=>{clearTimeout(autoTimer);const input=$('#fields textarea');if(!input)return;input.value=$('#output').value;$('#output').value='';$('#status').textContent='Đã chuyển kết quả sang đầu vào. Chọn thao tác tiếp theo.';$('#status').dataset.error='false';$('#status').style.color='';syncResult();rememberDraft();input.focus({preventScroll:true})};
$('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([$('#output').value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`toolhub-${current.id}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#dialog').addEventListener('close',()=>{clearTimeout(autoTimer);rememberDraft();document.querySelector(`[data-open="${current?.id}"]`)?.focus({preventScroll:true})});
$('#resetFilters').onclick=()=>{$('#search').value='';category=categories[0];view='all';render();$('#search').focus()};

$('#showResult').onclick=()=>document.querySelector('.output-pane').scrollIntoView({block:'start'});
